import math
from collections import deque

def bfs(graph, vertex1):
	queue = deque([vertex1])
	visited = {vertex1: True}
	while queue:
		v = queue.popleft()
		for n in graph[v]:
			if n not in visited:
				queue.append(n)
				visited[n] = True
	return visited

class findcycles:

	def __init__(self):
		self.allcycles = []
		self.stack = []
		self.blockset = []
		self.blockmap = {}

	def unblock(self, v):
		if v in self.blockset:
			self.blockset.remove(v)
		while v in self.blockmap:
			temp = self.blockmap[v]
			del self.blockmap[v]
			if temp in self.blockset:
				self.blockset.remove(temp)
			v = temp

	def johnson(self, adj, v, start):
		foundcycle = False
		self.stack.append(v)
		self.blockset.append(v)
		for i in adj[v]:
			if i == start:
				self.stack.append(start)
				cycle = self.stack.copy()
				self.stack.pop()
				self.allcycles.append(cycle)
				foundcycle = True
			elif i not in self.blockset:
				gotcycle = self.johnson(adj, i, start)
				foundcycle = foundcycle or gotcycle
		if foundcycle:
			self.unblock(v)
		else:
			for i in adj[v]:
				self.blockmap[i] = v
		self.stack.pop()
		return foundcycle

	def ret(self):
		if len(self.allcycles) > 0:
			self.allcycles.sort(key=lambda x: len(x))
			return self.allcycles[0]
		else:
			return []
